+              // A second finger must be able to exit while the first holds the stick.
+              if (event.pointerType === 'touch' && event.button === 0) {
+                event.preventDefault();
+                session.leaveRoom();
+              }
+            }}
+          >
+            <LogOut size={15} />
+            <span>Leave</span>
+          </Button>
+        )}
+      </div>
+    </header>
+  );
+}

