+  box-sizing: border-box;
+}
+body {
+  margin: 0;
+}
+button,
+input {
+  font: inherit;
+}
+button {
+  cursor: pointer;
+}
+button:disabled {
+  cursor: not-allowed;
+}
+a {
+  color: inherit;
+  text-decoration: none;
+}
+.game-shell {
+  height: 100dvh;
+  min-height: 600px;
+  display: flex;
+  flex-direction: column;
+}
+.topbar {
+  height: 64px;
+  flex-shrink: 0;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 24px;
+  padding: 0 30px;
+  border-bottom: 1px solid var(--border);
+  background: #11181a;
+  z-index: 20;
+}
+.brand {
+  display: flex;
+  gap: 7px;
+  align-items: center;
+  flex: none;
+  white-space: nowrap;
+  line-height: 1;
+  font-size: 25px;
+  font-weight: 900;
+  letter-spacing: -1.2px;
+}
+.brand span {
+  color: var(--primary);
+}
+.brand small {
+  margin-left: 20px;
+  font-size: 14px;
+  font-weight: 400;
+  line-height: 20px;
+  color: var(--muted-foreground);
+  letter-spacing: 1px;
+}
+.status {
+  font-size: 14px;
+  line-height: 20px;
+  display: flex;
+  align-items: center;
+  gap: 9px;
+  flex: none;
+  min-width: 0;
+  white-space: nowrap;
+  font-variant-numeric: tabular-nums;
+}
+.status svg {
+  flex: none;
+}
+.status i {
+  width: 7px;
+  height: 7px;
+  background: var(--primary);
+  border-radius: 50%;
+}
+.viewport {
+  position: relative;
+  flex: 1;
+  overflow: hidden;
+  background: radial-gradient(
+    ellipse at 70% 45%,
+    #284747,
+    #15282b 60%,
+    #11181a
+  );
+}
+.scene-label {
+  position: absolute;
+  top: 25px;
+  left: 30px;
+  font-size: 13px;
+  letter-spacing: 2px;
+  color: #aac2bd;
+}
+.start-panel {
+  position: absolute;
+  left: 7%;
+  top: 12%;
+  width: 330px;
+  padding: 28px;
+  background: #11181ae8;
+  border: 1px solid var(--border);
+  border-radius: 16px;
+}
+.eyebrow {
+  font-size: 12px;
+  letter-spacing: 3px;
+  color: var(--primary);
+}
+h1 {
+  font-size: clamp(40px, 5vw, 68px);
+  line-height: 1.1;
+  letter-spacing: -3px;
+  margin: 24px 0;
+}
+p {
+  color: var(--muted-foreground);
+  line-height: 1.7;
+  font-size: 15px;
+}
+.start-panel label {
+  display: block;
+  margin: 26px 0 9px;
+  font-size: 14px;
+}
+input[data-slot='input'] {
+  height: 42px;
+  font-size: 16px;
+}
+.primary[data-slot='button'] {
+  height: 46px;
+  width: 100%;
+  margin-top: 18px;
+  font-size: 16px;
+  background: var(--primary);
+  color: #152015;
+}
+.track-caption {
+  position: absolute;
+  bottom: 30px;
+  right: 30px;
+  color: #aec7c0;
+  font-size: 14px;
+}
+.topbar-hints {
+  color: #a6b6b5;
+  font-size: 13px;
+  line-height: 20px;
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  flex: none;
+  white-space: nowrap;
+  margin-right: auto;
+}
+.key-hint {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+}
+.topbar-hints kbd {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  height: 22px;
+  line-height: 16px;
+}
+.canvas-host {
+  position: absolute;
+  inset: 0;
+}
+.canvas-host canvas {
+  width: 100%;
+  height: 100%;
+  display: block;
+}
+.effects-control {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  color: #d2ded7;
+  font-size: 12px;
+}
+.effects-control svg {
+  color: #e5ff75;
+}
+.effects-control select {
+  color: #e5ff75;
+  background: #24312b;
+  border: 1px solid #ffffff18;
+  border-radius: 5px;
+  padding: 5px 4px;
+  min-width: 85px;
+  cursor: pointer;
+}
+.effects-control select:focus-visible {
+  outline: 2px solid #e5ff75;
+  outline-offset: 2px;
+}
+.header-right {
+  display: flex;
+  gap: 16px;
+  align-items: center;
+  min-width: 0;
+  margin-left: auto;
+}
+.header-right button[data-slot='button'] {
+  height: 36px;
+  font-size: 14px;
+  line-height: 20px;
+}
+.header-user[data-slot='button'] {
+  flex-shrink: 1;
+  min-width: 0;
+  max-width: 240px;
+}
+.header-name {
+  min-width: 0;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.header-user .muted {
+  flex: none;
+}
+.header-exit[data-slot='button'] {
+  flex: none;
+  gap: 5px;
+  padding: 0 8px;
+  color: #dce7df;
+}
+.avatar {
+  display: grid;
+  place-items: center;
+  background: #314b45;
+  color: #d9ff5f;
+  border: 1px solid #90ae4e;
+  border-radius: 50%;
+  width: 27px;
+  height: 27px;
+  font-size: 12px;
+  flex: none;
+}
+.muted {
+  color: var(--muted-foreground);
+  margin-left: 8px;
+}
+.offline {
+  color: #9cabaa;
+}
+.rename {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  min-width: 0;
+}
+.rename input {
+  width: 150px !important;
+  height: 36px !important;
+  min-width: 0;
+}
+.live-dot {
+  display: inline-block;
+  width: 6px;
+  height: 6px;
+  flex-shrink: 0;
+  background: #d9ff5f;
+  border-radius: 50%;
+}
+.scene-label {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  background: #11181a9e;
+  padding: 8px 12px;
+  border-radius: 6px;
+  backdrop-filter: blur(12px);
+  top: 18px;
+  font-size: 12px;
+  color: #e5efeb;
+}
+.slash {
+  opacity: 0.35;
+  margin: 0 4px;
+}
+.panel {
+  background: #172225ed;
+  border: 1px solid #ffffff18;
+  border-radius: 12px;
+}
+.garage-panel {
+  position: absolute;
+  top: 24px;
+  left: 30px;
+  width: 330px;
+  padding: 24px;
+  max-height: calc(100% - 48px);
+  overflow: auto;
+  scrollbar-width: thin;
+}
+.panel-heading {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  gap: 10px;
+}
+.panel h2 {
+  margin: 7px 0 14px;
+  font-size: 24px;
+  font-weight: 650;
+  letter-spacing: -0.5px;
+}
+.panel-heading > svg {
+  color: #d9ff5f;
+  margin-bottom: 14px;
+}
+/* Full-width rows leave room for a route silhouette and a readable caption. */
+.map-options {
+  grid-template-columns: minmax(0, 1fr);
+  gap: 8px !important;
+}
+.map-card {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  padding: 10px 11px;
+  border: 1px solid #ffffff14;
+  background: #ffffff04;
+  border-radius: 9px;
+  cursor: pointer;
+  transition: background 0.15s;
+}
+.map-card:hover {
+  background: #ffffff0c;
+}
+.map-card.selected {
+  border-color: var(--map-color);
+  background: color-mix(in srgb, var(--map-color) 8%, transparent);
+}
+.map-card:focus-within {
+  outline: 2px solid white;
+  outline-offset: 2px;
+}
+.map-number {
+  font-size: 19px;
+  color: var(--map-color);
+  font-variant-numeric: tabular-nums;
+  font-weight: 300;
+  letter-spacing: -1px;
+}
+.map-card strong {
+  font-size: 13px;
+  font-weight: 550;
+  display: block;
+}
+/* The track's own caption is in the scene label; the card stays one line. */
+.map-card small {
+  display: none;
+}
+.map-card svg {
+  display: none;
+}
+.mode-description {
+  font-size: 12px;
+  margin: 9px 0 0;
+}
+.panel-subheading {
+  font-size: 12px;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: #99adaa;
+  margin: 20px 0 8px;
+}
+.skin-picker {
+  grid-template-columns: 1fr 1fr;
+  gap: 7px !important;
+}
+.skin-chip {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  padding: 8px 10px;
+  border: 1px solid #ffffff1c;
+  background: #ffffff04;
+  border-radius: 7px;
+  font-size: 13px;
+  color: inherit;
+  cursor: pointer;
+  transition: background 0.15s;
+}
+.skin-chip:hover:not(:disabled) {
+  background: #ffffff0c;
+}
+.skin-chip.selected {
+  border-color: var(--skin-color);
+  background: color-mix(in srgb, var(--skin-color) 14%, transparent);
+}
+.skin-chip:focus-within {
+  outline: 2px solid white;
+  outline-offset: 2px;
+}
+.skin-chip.taken {
+  opacity: 0.35;
+  cursor: not-allowed;
+  text-decoration: line-through;
+}
+.skin-dot {
+  width: 13px;
+  height: 13px;
+  flex: none;
+  border-radius: 50%;
+  background: var(--skin-color);
+  box-shadow: 0 0 0 1px #00000055 inset;
+}
+.garage-panel .primary {
+  margin-top: 12px;
+}
+.join-form {
+  display: flex;
+  gap: 7px;
+  margin-top: 12px;
+}
+.join-form input[data-slot='input'] {
+  font-size: 14px;
+  height: 36px;
+}
+.join-form button {
+  height: 36px !important;
+}
+.room-list {
+  border-top: 1px solid #ffffff17;
+  margin-top: 20px;
+  padding-top: 17px;
+}
+.section-label {
+  font-size: 12px;
+  letter-spacing: 1px;
+  color: #afc1bb;
+  display: flex;
+  gap: 7px;
+  align-items: center;
+  margin-bottom: 10px;
+}
+.section-label > span {
+  margin-left: auto;
+}
+.hint {
+  color: #90a5a1;
+  font-size: 12px;
+  line-height: 1.65;
+  display: block;
+}
+.room-row[data-slot='button'] {
+  display: flex;
+  justify-content: space-between;
+  width: 100%;
+  font-size: 12px;
+  padding: 8px 0;
+  height: auto;
+  white-space: normal;
+  text-align: left;
+}
+.room-row small {
+  font-size: 12px;
+  color: #aabbaf;
+}
+.policy-card {
+  margin: 14px 0;
+  padding: 12px;
+  border: 1px solid #d9ff5f35;
+  border-radius: 9px;
+  background: #d9ff5f08;
+  min-width: 0;
+}
+.garage-panel > .policy-card {
+  margin-top: 0;
+  margin-bottom: 20px;
+}
+.policy-card .panel-subheading {
+  margin: 0;
+  font-size: 12px;
+  color: #a6b6b5;
+}
+.policy-name {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  margin: 6px 0 12px;
+  font-size: 13px;
+  font-weight: 550;
+}
+.policy-name > span:last-child {
+  min-width: 0;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.policy-actions {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+.policy-actions .upload-policy[data-slot='button'] {
+  flex: 1;
+  height: 35px;
+  padding: 0 10px;
+  gap: 6px;
+  font-size: 12px;
+  background: #d9ff5f;
+  color: #152015;
+}
+.policy-actions .restore[data-slot='button'] {
+  flex: none;
+  width: auto;
+  margin: 0;
+  padding: 0 5px;
+  height: 35px;
+  gap: 5px;
+  font-size: 11px;
+  color: #b5c5bc;
+}
+.policy-requirements {
+  margin-top: 10px;
+  font-size: 10px;
+  color: #94a89b;
+}
+.policy-requirements summary {
+  cursor: pointer;
+}
+.policy-requirements p {
+  font-size: 11px;
+  line-height: 1.5;
+  margin: 6px 0 0;
+}
+.policy-card .policy-help {
+  display: block;
+}
+.engine-state {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  color: #a6b9b1;
+  font-size: 12px;
+  min-width: 0;
+}
+/* The policy name can be long; the summary line stays one line. */
+.engine-state > span:last-child {
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.engine-state:not(.ok) .live-dot {
+  background: #ffa669;
+}
+.policy-help {
+  font-size: 11px;
+  margin: 6px 0 0;
+  line-height: 1.55;
+}
+.start-panel {
+  left: 7%;
+  top: 15%;
+  width: 360px;
+  padding: 32px;
+}
+.start-panel h1 {
+  font-size: 34px;
+  letter-spacing: -1px;
+  margin: 0 0 24px;
+}
+.start-panel .hint {
+  margin-top: 15px;
+}
+.primary[data-slot='button'] {
+  display: flex;
+  justify-content: center;
+  gap: 14px;
+  border: 1px solid #e9ff92;
+  font-weight: 600;
+}
+.primary:disabled {
+  opacity: 0.42;
+}
+.room-panel {
+  position: absolute;
+  top: 24px;
+  left: 30px;
+  width: 305px;
+  padding: 23px;
+  max-height: calc(100% - 48px);
+  overflow-y: auto;
+}
+.room-panel h2 {
+  font-size: 22px;
+  letter-spacing: 1px;
+  display: flex;
+  align-items: center;
+  margin-bottom: 12px;
+}
+.room-panel h2 button {
+  margin-left: 5px;
+  letter-spacing: 0;
+}
+.room-meta {
+  display: flex;
+  justify-content: space-between;
+  color: #b0bdb8;
+  font-size: 12px;
+  border-bottom: 1px solid #ffffff1c;
+  padding-bottom: 17px;
+}
+.leaderboard {
+  list-style: none;
+  margin: 14px -10px 0;
+  padding: 0;
+}
+.leaderboard li {
+  display: flex;
+  gap: 9px;
+  align-items: center;
+  padding: 12px 10px;
+  border-radius: 6px;
+  font-size: 14px;
+}
+.leaderboard .self {
+  background: #d9ff5f12;
+}
+.position {
+  font-size: 13px;
+  color: #82998e;
