+}
+.player-name small {
+  font-size: 10px;
+  background: #ffffff17;
+  border-radius: 3px;
+  padding: 1px 4px;
+  flex-shrink: 0;
+  white-space: nowrap;
+}
+.player-state {
+  font-size: 12px;
+  color: #c5d99a;
+  white-space: nowrap;
+}
+.start-race[data-slot='button'] {
+  height: 41px;
+  width: 100%;
+  margin: 8px 0 13px;
